    tips: {
      de: 'seit + 第三格表示一件事从过去持续到现在，德语用现在时：Ich suche seit einem Monat eine Stelle（我找工作已经一个月了）。“对……感兴趣”是 sich für + 第四格 interessieren：Ich interessiere mich für die Stelle。',
      den: 'seit + dative says how long something has been going on, and German uses the present tense where English says "have been": Ich suche seit einem Monat eine Stelle (I have been looking for a job for a month). "To be interested in" is sich für + accusative interessieren: Ich interessiere mich für die Stelle.'
    },
