      de: 'aber、oder、sondern 后面的语序不变。weil、dass、wenn、ob 引导从句，变位动词放在从句末尾：…, weil ich krank bin。deshalb、trotzdem、also、außerdem 占句子的第一位，动词紧跟在后面：deshalb kann ich nicht kommen。',
      den: "After aber, oder and sondern the word order doesn't change. weil, dass, wenn and ob start a clause with the conjugated verb at the end: …, weil ich krank bin. deshalb, trotzdem, also and außerdem fill the first position, so the verb comes straight after: deshalb kann ich nicht kommen."
